"""
AI模拟面试官 — DeepSeek V4 LLM 服务
负责：C同学
"""
import requests
import os
import logging

logger = logging.getLogger(__name__)

# 从环境变量读取密钥；也可直接填入默认值用于开发
DEEPSEEK_API_KEY = os.environ.get("DEEPSEEK_API_KEY", "sk-***REDACTED***")
DEEPSEEK_API_URL = "https://api.deepseek.com/chat/completions"
DEEPSEEK_MODEL = "deepseek-v4-pro"


def llm_interview(role: str, history: list, state: str, audio_base64: str = "") -> dict:
    try:
        system_prompt = (
            f"你是一位专业的面试官，正在面试{role}岗位的候选人。"
            "请用中文回答。你要根据候选人的回答，提出有深度的问题或给出反馈。"
            "语气专业、友好、有洞察力。"
        )

        messages = [{"role": "system", "content": system_prompt}]

        for msg in history:
            role_map = {"user": "user", "ai": "assistant"}
            messages.append({"role": role_map.get(msg["role"], "user"), "content": msg["content"]})

        if audio_base64 and len(history) == 0:
            messages.append({
                "role": "user",
                "content": "（候选人已准备好，请开始面试并提出第一个问题）"
            })

        headers = {
            "Authorization": f"Bearer {DEEPSEEK_API_KEY}",
            "Content-Type": "application/json"
        }

        payload = {
            "model": DEEPSEEK_MODEL,
            "messages": messages,
            "stream": False,
            "max_tokens": 1024,
            "temperature": 0.8,
            "thinking": {"type": "disabled"}
        }

        logger.info(f"DeepSeek请求: model={DEEPSEEK_MODEL}, 消息数={len(messages)}")
        resp = requests.post(DEEPSEEK_API_URL, headers=headers, json=payload, timeout=30)
        resp.raise_for_status()
        data = resp.json()

        ai_text = data["choices"][0]["message"]["content"]
        next_action = "finish" if len(history) >= 20 else "continue"

        logger.info(f"DeepSeek返回: {ai_text[:100]}...")
        return {"text": ai_text, "next_action": next_action}

    except Exception as e:
        logger.error(f"DeepSeek调用失败: {e}")
        return {"text": "抱歉，我暂时无法回答，请重试。", "next_action": "continue"}

